import{_ as a,C as o,o as s,c as i,j as t,a as r,E as d,a2 as c}from"./chunks/framework.Dx82uCjM.js";const f=JSON.parse('{"title":"Connect a machine","description":"Connect the computer your agents will run on, once, then add its repositories.","frontmatter":{"title":"Connect a machine","description":"Connect the computer your agents will run on, once, then add its repositories."},"headers":[],"relativePath":"guide/connect-a-machine.md","filePath":"guide/connect-a-machine.md","lastUpdated":1790947452000}'),h={name:"guide/connect-a-machine.md"};function l(p,e,u,g,m,k){const n=o("TutorialVideo");return s(),i("div",null,[e[0]||(e[0]=t("h1",{id:"connect-a-machine",tabindex:"-1"},[r("Connect a machine "),t("a",{class:"header-anchor",href:"#connect-a-machine","aria-label":'Permalink to "Connect a machine"'},"​")],-1)),d(n,{n:"01"}),e[1]||(e[1]=c('<p>Agents run on your own machines, never on ours. A machine you connect is called a <strong>runner</strong>.</p><p>The machine needs Node.js (for <code>npx</code>), your repositories cloned, and at least one coding agent installed and signed in: Claude Code, Codex, OpenCode or Gemini CLI. The runner finds them by itself, and each ticket can pick any agent its machine has.</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to &quot;Steps&quot;">​</a></h2><ol><li><p>Open a terminal, in any folder (your home folder is fine), and run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tackora@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> start</span></span></code></pre></div><p>It prints a link and an 8-character code.</p></li><li><p>Open the link (or go to <strong>Runners</strong> and type the code). Check the code is the one your terminal shows, then press <strong>Connect</strong>.</p></li><li><p>The terminal says <strong>Tackora is running in the background</strong> and gives you the prompt back. The runner keeps going, starts again when you log in, and shows up on the Runners page.</p></li><li><p>In each repository&#39;s folder, run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tackora@latest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span></span></code></pre></div><p>The runner picks it up within 15 seconds and works on that repository&#39;s tickets.</p></li></ol><p><code>npx tackora@latest remove</code> in a folder stops working on that repository (its files stay as they are). <code>npx tackora@latest stop</code> takes the machine offline until you run <code>start</code> again.</p><p>On Linux the runner is a systemd user service, on macOS a launchd agent, on Windows a task that starts at logon. Its output is in <code>~/.tackora/runner.log</code> (<code>npx tackora@latest logs</code>). It takes the API keys of the shell you ran <code>start</code> in (for example <code>ANTHROPIC_API_KEY</code>): after changing one, run <code>start</code> again.</p><h2 id="all-commands" tabindex="-1">All commands <a class="header-anchor" href="#all-commands" aria-label="Permalink to &quot;All commands&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>What it does</th></tr></thead><tbody><tr><td><code>start</code></td><td>Connect this machine (the first time), then run in the background, starting again at login. It updates itself within an hour of a new version, once no ticket is running.</td></tr><tr><td><code>add [folder]</code></td><td>Work on a repository: the folder you&#39;re in, or the one you name.</td></tr><tr><td><code>remove [folder]</code></td><td>Stop working on a repository. Its folder stays as it is.</td></tr><tr><td><code>status</code></td><td>Whether it&#39;s running, its repositories and the agents it found.</td></tr><tr><td><code>logs</code></td><td>What the background runner printed. <code>logs -f</code> keeps following it.</td></tr><tr><td><code>stop</code></td><td>Stop the background runner: the machine goes offline until <code>start</code> runs again.</td></tr><tr><td><code>start --foreground</code></td><td>Run in the terminal instead, for servers, containers or debugging. Ctrl+C stops it and its agents.</td></tr><tr><td><code>--version</code></td><td>Which runner version this is.</td></tr></tbody></table>',8))])}const b=a(h,[["render",l]]);export{f as __pageData,b as default};
